}.bp-dialog-title { font-size: 16px; font-weight: 600; color: rgb(173, 198, 255); margin: 0px; display: flex; align-items: center; gap: 8px; }.bp-dialog-desc { font-size: 14px; color: rgb(193, 198, 215); margin: 0px; line-height: 1.5; }.bp-dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 12px; }.bp-dialog-btn { padding: 8px 16px; border-radius: 6px; font-size: 13px; font-weight: 500; cursor: pointer; transition: 0.2s; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }.bp-dialog-btn-cancel { background: rgba(255, 255, 255, 0.1); color: rgb(193, 198, 215); }.bp-dialog-btn-cancel:hover { background: rgba(255, 255, 255, 0.15); color: rgb(228, 226, 228); }.bp-dialog-btn-stop { background: rgba(147, 0, 10, 0.3); color: rgb(255, 180, 171); }.bp-dialog-btn-stop:hover { background: rgba(147, 0, 10, 0.4); }.bp-badge { position: fixed; bottom: 20px; right: 20px; z-index: 2147483646; background: rgba(19, 19, 21, 0.85); backdrop-filter: blur(24px) saturate(180%); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 9999px; padding: 6px 14px 6px 10px; display: flex; align-items: center; gap: 10px; cursor: pointer; font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif; box-shadow: rgba(0, 0, 0, 0.4) 0px 10px 30px, rgba(255, 255, 255, 0.05) 0px 1px 1px inset; transition: 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); user-select: none; pointer-events: auto; }.bp-badge:hover { background: rgba(25, 25, 28, 0.95); border-color: rgba(0, 122, 255, 0.4); transform: translateY(-2px); box-shadow: rgba(0, 122, 255, 0.2) 0px 12px 35px, rgba(255, 255, 255, 0.05) 0px 1px 1px inset; }.bp-badge:active { transform: translateY(0px); }.bp-badge-title { font-weight: 600; font-size: 13px; color: rgb(228, 226, 228); letter-spacing: -0.01em; }.bp-badge-status { font-size: 10px; font-weight: 700; color: rgb(173, 198, 255); text-transform: uppercase; letter-spacing: 0.05em; background: rgba(0, 122, 255, 0.15); padding: 2px 8px; border-radius: 9999px; border: 1px solid rgba(0, 122, 255, 0.25); }.bp-chat-bubble { position: absolute; bottom: 130%; left: 23px; transform: translateX(-50%) translateY(10px); background: rgb(42, 42, 44); padding: 8px 12px; border-radius: 8px; color: rgb(228, 226, 228); font-size: 11px; font-weight: 500; font-family: var(--bp-font-family); box-shadow: rgba(0, 0, 0, 0.4) 0px 12px 24px, rgba(255, 255, 255, 0.05) 0px 0px 0px 1px; opacity: 0; pointer-events: auto; transition: 0.3s cubic-bezier(0.2, 0.8, 0.2, 1); white-space: nowrap; display: flex; gap: 12px; align-items: center; }.bp-chat-bubble.visible { opacity: 1; transform: translateX(-50%) translateY(0px); }.bp-chat-bubble::after { content: ""; position: absolute; bottom: -4px; left: 50%; width: 10px; height: 10px; margin-left: -5px; background: rgb(42, 42, 44); box-shadow: rgba(255, 255, 255, 0.05) 1px 1px 0px; transform: rotate(45deg); }.bp-bubble-stop-btn { background: rgba(147, 0, 10, 0.3); color: rgb(255, 180, 171); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; padding: 4px 8px; border-radius: 4px; cursor: pointer; font-size: 10px; font-weight: 600; font-family: var(--bp-font-family); transition: background 0.2s; }.bp-bubble-stop-btn:hover { background: rgba(147, 0, 10, 0.5); }
